export function init({q}){
  const cats=[
    ['Shoes','👟','Footwear for daily rotation and sport.','https://findspreadsheet.com/category/shoes'],
    ['Clothing','🧥','Tees, hoodies, jackets and trousers.','https://findspreadsheet.com/category/clothing'],
    ['Bags','👜','Carry pieces for everyday and travel.','https://findspreadsheet.com/category/bags'],
    ['Accessories','⌚','Watches, eyewear, belts and details.','https://findspreadsheet.com/category/accessories'],
    ['Watches','◷','Dress, sport and everyday timepieces.','https://findspreadsheet.com/category/watches'],
    ['Jewellery','✦','Chains, rings, bracelets and small goods.','https://findspreadsheet.com/category/jewellery'],
    ['Electronics','◉','Audio and practical consumer technology.','https://findspreadsheet.com/category/electronics'],
    ['Beauty','✺','Fragrance and care essentials.','https://findspreadsheet.com/category/beauty'],
    ['Hats','⌒','Caps, beanies and headwear.','https://findspreadsheet.com/category/hats'],
    ['Socks','≋','Daily and sport-ready basics.','https://findspreadsheet.com/category/socks']
  ];
  const style=document.createElement('style');style.textContent=`
  :root{--paper:#120F1D;--ink:#F7F3FA;--muted:#C9C2D0;--line:#D8D5E2;--purple:#A855F7;--violet:#8A2BE2;--panel:#1B1725}.shell{max-width:1420px}.topline,.nav{background:#120F1D;color:#F7F3FA;border-color:rgba(216,213,226,.32)}.nav{position:sticky;top:0;z-index:20}.lang{background:#1B1725;color:#fff;border-color:rgba(216,213,226,.45)}.database,.primary{background:#8A2BE2;box-shadow:0 0 0 1px rgba(168,85,247,.42),0 0 20px rgba(138,43,226,.38)}.hero,.section,.page-hero{border-color:rgba(216,213,226,.32)}.hero h1,.page-title,.section h2,.entry h3{color:#F7F3FA}.hero p,.section-head p,.page-lead,.article p,.footer p{color:#C9C2D0}.search{border-color:#D8D5E2;background:#fff}.manifesto,.feature.dark{background:#0A0A0A}.feature{background:#1B1725;border:1px solid rgba(216,213,226,.22);color:#fff}.feature p,.feature.purple p,.feature.dark p{color:#C9C2D0}.feature.purple{background:#8A2BE2;border-color:#A855F7}.steps .step{border-color:#A855F7}.step p{color:#C9C2D0}.footer{color:#fff}.category-matrix{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;padding:4px 0 10px}.category-tile{min-height:118px;padding:13px;border:1px solid rgba(216,213,226,.36);border-radius:11px;background:#1B1725;color:#F7F3FA;text-align:left;cursor:pointer;display:flex;flex-direction:column;justify-content:space-between;transition:.18s}.category-tile:hover,.category-tile:focus-visible{outline:0;border-color:#A855F7;box-shadow:0 0 0 2px rgba(168,85,247,.46),0 0 23px rgba(138,43,226,.42);transform:translateY(-2px)}.cat-no{font:10px 'DM Mono',monospace;color:#C9B3E9}.cat-icon{font-size:23px;line-height:1}.cat-name{font-weight:800;font-size:15px;letter-spacing:-.04em}.category-drawer{position:fixed;z-index:45;top:0;right:0;width:min(430px,100%);height:100dvh;padding:28px;background:#17131F;color:#F7F3FA;border-left:1px solid rgba(216,213,226,.42);box-shadow:-20px 0 48px rgba(0,0,0,.42);transform:translateX(104%);transition:transform .26s}.category-drawer.open{transform:translateX(0)}.drawer-close{position:absolute;right:18px;top:14px;background:transparent;border:0;color:#fff;font-size:28px;cursor:pointer}.drawer-label{font:11px 'DM Mono',monospace;color:#C9B3E9}.drawer-preview{margin:28px 0 19px;min-height:205px;border:1px solid rgba(216,213,226,.37);border-radius:12px;background:radial-gradient(circle at 70% 24%,#A855F7 0,rgba(168,85,247,.25) 19%,transparent 20%),linear-gradient(135deg,#0A0A0A,#2D1846);display:grid;place-items:center;font-size:80px}.category-drawer h2{font:800 48px/.9 Manrope,Arial,sans-serif;letter-spacing:-.08em;margin:0 0 13px}.category-drawer p{color:#C9C2D0}.drawer-go{display:inline-block;margin-top:16px;padding:13px 15px;border-radius:8px;background:#8A2BE2;color:#fff;font-size:12px;font-weight:900;box-shadow:0 0 20px rgba(138,43,226,.45)}@media(max-width:760px){.shell{padding:0 16px}.nav{padding:14px 0}.navlinks{gap:11px;font-size:11px;overflow-x:auto;padding-bottom:6px}.navtools{gap:5px}.database{padding:9px 10px}.category-matrix{grid-template-columns:repeat(2,1fr);gap:9px}.category-tile{min-height:92px}.hero{padding-top:32px}.feature-grid,.steps,.card-list{grid-template-columns:1fr}}
  `;document.head.append(style);
  if((location.pathname.replace(/\/$/,'')||'/')!=='/')return;
  const section=[...document.querySelectorAll('.section')].find(s=>s.querySelector('.entries'));if(!section)return;
  const head=section.querySelector('.section-head');if(head)head.innerHTML='<h2>10 product directions</h2><p>Hover a category for a visual preview. Click to open its product detail drawer.</p>';
  const entries=section.querySelector('.entries');entries.className='category-showcase';entries.innerHTML=`<aside class="cat-hover-preview"><span class="drawer-label">HOVER PREVIEW</span><div id="hover-icon">👟</div><b id="hover-name">Shoes</b><p id="hover-copy">Footwear for daily rotation and sport.</p></aside><div class="category-matrix">${cats.map((c,i)=>`<button class="category-tile" data-cat="${i}"><span class="cat-no">${String(i+1).padStart(2,'0')}</span><span class="cat-icon">${c[1]}</span><span class="cat-name">${c[0]}</span></button>`).join('')}</div>`;const previewStyle=document.createElement('style');previewStyle.textContent='.category-showcase{display:grid;grid-template-columns:190px 1fr;gap:12px}.cat-hover-preview{border:1px solid rgba(216,213,226,.36);border-radius:11px;background:linear-gradient(150deg,#0A0A0A,#271738);padding:16px;color:#F7F3FA}.cat-hover-preview #hover-icon{font-size:50px;line-height:1;margin:18px 0}.cat-hover-preview b{font-size:19px;letter-spacing:-.05em}.cat-hover-preview p{font-size:11px;line-height:1.4;color:#C9C2D0;margin:6px 0}.category-showcase .category-matrix{padding:0}@media(max-width:760px){.category-showcase{grid-template-columns:1fr}.cat-hover-preview{display:flex;align-items:center;gap:11px;padding:12px}.cat-hover-preview #hover-icon{font-size:32px;margin:0}.cat-hover-preview p{margin:0}.cat-hover-preview .drawer-label{display:none}}';document.head.append(previewStyle);
  const drawer=document.createElement('aside');drawer.className='category-drawer';drawer.innerHTML='<button class="drawer-close" aria-label="Close">×</button><span class="drawer-label">CATEGORY PREVIEW</span><div class="drawer-preview" id="drawer-preview">👟</div><h2 id="drawer-title">Shoes</h2><p id="drawer-desc">Footwear for daily rotation and sport.</p><a class="drawer-go" id="drawer-go" href="https://findspreadsheet.com">OPEN SELECTION →</a>';document.body.append(drawer);
  const set=i=>{const c=cats[i];q('#hover-icon').textContent=c[1];q('#hover-name').textContent=c[0];q('#hover-copy').textContent=c[2];q('#drawer-preview').textContent=c[1];q('#drawer-title').textContent=c[0];q('#drawer-desc').textContent=c[2];q('#drawer-go').href=c[3]};document.querySelectorAll('.category-tile').forEach(btn=>{const i=Number(btn.dataset.cat);btn.addEventListener('mouseenter',()=>set(i));btn.addEventListener('focus',()=>set(i));btn.addEventListener('click',()=>{set(i);drawer.classList.add('open')})});drawer.querySelector('.drawer-close').onclick=()=>drawer.classList.remove('open');
}
